	const norm = (p: string) => p.replace(/\\/g, "/").replace(/\/$/, "");
	const np = norm(absPath);
	const nc = norm(cwd);
	if (np === nc) return false;
	return !np.startsWith(`${nc}/`);
}

function resolvePath(cwd: string, p: unknown): string {
	if (typeof p !== "string") return "";
	if (!p) return "";
	return resolve(cwd, p);
}

