function extractAssistantText(messages: unknown[]): string {
	for (let i = messages.length - 1; i >= 0; i--) {
		const msg = messages[i] as any;
		if (msg?.role !== "assistant") continue;
		const parts = Array.isArray(msg.content) ? msg.content : [];
