	const jobs = listJobs();
	const count = (s: string) => jobs.filter((j) => j.state === s).length;
	const next = jobs
		.filter((j) => j.enabled && j.state === "scheduled" && j.nextRunAt)
		.sort((a, b) => String(a.nextRunAt).localeCompare(String(b.nextRunAt)))[0];
