		`Cron: scheduler ${scheduler ? "running" : "stopped"}; ${jobs.length} job(s) — ` +
		`${count("scheduled")} scheduled, ${count("paused")} paused, ${count("completed")} completed, ${count("error")} error.` +
		(next ? ` Next: '${next.name}' at ${fmtTime(next.nextRunAt)}.` : "")
	);
